fn stale(mut f: ApplyOutcomeFacts, bit: usize) -> ApplyOutcomeFacts {
    match bit { 0 => f.peer.exact_peer = false, 1 => f.peer.current_generation = 2,
        2 => f.exact_source = false, 3 => f.exact_sink = false,
        4 => f.exact_capture_authorization = false, 5 => f.exact_forwarding_authorization = false,
        6 => f.capture_authorization_valid = false, 7 => f.forwarding_authorization_valid = false,
        8 => f.sink_allows_active_use = false, 9 => f.exact_base_dimensions = false,
        _ => panic!("fixture") }; f
}
