fn observed_negative(mut p: Prepared) -> Prepared {
    p.policy.startup_disproved = true; p.policy.floor_attempt_consumed = true;
    p.policy.floor_regular_sequence = Some(41); p.policy.floor_regular_timestamp = Some(Scalar::new(41_000_000.0));
    // Deliberately unrelated proposed positive state must never be imported by retention.
    p.policy.probe_deadline = Some(9_999 * MS); p.policy.queue.low_observation = Some(9_998 * MS);
    p.policy.rtt.last_advancement = Some(9_997 * MS); p.policy.probe_maximum = Some(999_999); p
}
fn clear(p: &mut Policy, slot: TimeSlot) {
    match slot { TimeSlot::QueueLow | TimeSlot::QueueSoft => { p.queue.times.clear::<i128>(slot); },
        TimeSlot::RttAdvancement => { p.rtt.times.clear::<i128>(slot); },
        _ => { p.times.clear::<i128>(slot); } }
}
fn corresponding(p: &mut Policy) {
    // Literal nine corresponding-prepared assignments from native whole-policy adoption.
    let values = [p.probe_deadline, p.probe_qualification_at, p.promotion.map(|x| x.deadline),
        p.floor_first_witness.map(|x| x.observed_at), p.floor_cooldown_at, p.startup_sparse_deadline,
        p.queue.low_observation, p.queue.soft_observation, p.rtt.last_advancement];
    for (slot, value) in SLOTS.into_iter().take(9).zip(values) {
        let journal = match slot { TimeSlot::QueueLow | TimeSlot::QueueSoft => &mut p.queue.times,
            TimeSlot::RttAdvancement => &mut p.rtt.times, _ => &mut p.times };
        if let Some(value) = value { journal.set(slot, value, Some(Origin {
            source: TimeSource::CorrespondingPreparedInput(slot), delta: 0 })); }
        else { journal.clear::<i128>(slot); }
    }
}
fn negative_prefix(v: &mut Owner, incoming: Prepared) {
    // Fixtures satisfy the exact peer/Show guards and increasing finite timestamp.
    v.policy.startup_disproved = true; v.policy.startup_sparse_deadline = None;
    clear(&mut v.policy, TimeSlot::SparseDeadline);
    v.policy.floor_attempt_consumed = true; v.policy.floor_first_witness = None;
    clear(&mut v.policy, TimeSlot::FloorWitness);
    v.policy.floor_regular_sequence = incoming.policy.floor_regular_sequence;
    v.policy.floor_regular_timestamp = incoming.policy.floor_regular_timestamp;
}
fn before_revert_cut(p: &mut Policy) {
    // Retire-floor and resetQueueForTier BEFORE Q; no queue/trailing probe cleanup yet.
    p.floor_probe_cancelled = true; p.floor_seed = None; p.tier = Tier::AudioPriority;
    p.floor_first_witness = None; clear(p, TimeSlot::FloorWitness);
    p.capacity_sample = None; p.capacity_bandwidth_high = None;
    p.promotion = None; clear(p, TimeSlot::PromotionDeadline);
}
fn after_revert_cut(p: &mut Policy) {
    // Tier reset retains cumulative packets/delay, unlike a path reset.
    p.queue.pressure_count = 0;
    p.queue.low_observation = None; p.queue.soft_observation = None;
    clear(p, TimeSlot::QueueLow); clear(p, TimeSlot::QueueSoft);
    p.probe_origin = None; p.probe_confirmed = None; p.probe_qualification_at = None;
    clear(p, TimeSlot::ProbeQualification); p.probe_best = None; p.probe_maximum = None;
    p.probe_healthy = 0; p.probe_grace = 0; p.probe_deadline = None; clear(p, TimeSlot::ProbeDeadline);
    p.promotion = None; clear(p, TimeSlot::PromotionDeadline);
    p.startup_disproved = true; p.startup_sparse_deadline = None; clear(p, TimeSlot::SparseDeadline);
    p.healthy_upgrades = 0; p.limited_upgrades = 0;
}
fn wire(v: Owner) -> Vec<state_codec::Atom> {
    let w = state_codec::encode_owner(v, state_codec::RESULT).unwrap();
    assert_eq!(w.header,state_codec::Header {abi:1,domain:2,phase:2,count:179});
    assert_eq!(w.atoms.len(), 179); w.atoms
}
fn prepared_wire(v: Prepared) -> Vec<state_codec::Atom> {
    let w = state_codec::encode_prepared_continuation(v).unwrap();
    assert_eq!(w.header,state_codec::Header {abi:1,domain:4,phase:3,count:222});
    assert_eq!(w.atoms.len(), 222); w.atoms
}
fn policy_journals(actual: Policy, expected: Policy) {
    for (a,e) in [(actual.times,expected.times),(actual.queue.times,expected.queue.times),
        (actual.rtt.times,expected.rtt.times)] {
        assert_eq!(a.valid(), e.valid());
        for slot in SLOTS { assert_eq!(a.edit(slot),e.edit(slot),"journal edit {slot:?}");
            assert_eq!(a.origin(slot),e.origin(slot),"journal origin {slot:?}"); }
    }
}
fn whole(actual: Owner, expected: Owner) {
    assert_eq!(wire(actual), wire(expected), "all179, IEEE words and opaque owner tail");
    policy_journals(actual.policy, expected.policy);
    assert_eq!(actual.times.valid(), expected.times.valid());
    for slot in SLOTS { assert_eq!(actual.times.edit(slot), expected.times.edit(slot));
        assert_eq!(actual.times.origin(slot), expected.times.origin(slot)); }
}
fn whole_prepared(actual: Prepared, expected: Prepared) {
    assert_eq!(prepared_wire(actual), prepared_wire(expected), "all222, diagnostics/route/revisions");
    policy_journals(actual.policy, expected.policy);
}
fn deny(ordinal: usize, site: ClockSite) -> Denied { Denied::Cut { ordinal, site } }

#[test]
fn continuation_clock_inactive_stale_guards_use_expected_not_applying_revision_zero_cut() {
    let seed = healthy(owner()); let input = prepared(seed);
    for bit in 0..3 {
        let mut v = seed; let mut p = input; let mut f = peer();
        match bit { 0 => f.exact_peer = false, 1 => f.current_generation = 2,
            _ => p.expected_revision = 58 }
        p.applying_revision = seed.revision; let mut c = NativeCuts::default();
        assert_eq!(v.try_adopt_inactive(p,f,true,&mut c,Dependencies::default()),
            Ok(InactiveProjection { disposition: InactiveDisposition::StaleReturn, route_action: RouteAction::Retain }));
        assert!(c.calls.is_empty()); whole(v,seed); whole_prepared(input,prepared(seed));
    }
    let mut v = seed; let mut p = input; p.applying_revision = 99;
    let mut c = NativeCuts::default(); let mut expected = seed;
    expected.policy = p.policy; corresponding(&mut expected.policy);
    expected.policy.suspension_pressure = 0; expected.policy.maximum_resume = 0; expected.policy.stable_resume = 0;
    expected.revision = 58;
    assert_eq!(v.try_adopt_inactive(p,peer(),false,&mut c,Dependencies::default()),
        Ok(InactiveProjection { disposition: InactiveDisposition::Adopted, route_action: RouteAction::CopyIncoming }));
    assert!(c.calls.is_empty()); whole(v,expected);
}

#[test]
fn continuation_clock_inactive_equal_coordinates_require_all_corresponding_origins() {
    let mut seed = healthy(probe(owner())); seed.policy.stable_resume = 4;
    seed.policy.maximum_resume = 2; seed.policy.suspension_pressure = 9;
    let p = prepared(seed); let before = prepared_wire(p); let mut v = seed; let mut c = NativeCuts::default();
    let mut expected = seed; corresponding(&mut expected.policy);
    expected.policy.stable_resume = 0; expected.policy.maximum_resume = 0; expected.policy.suspension_pressure = 0;
    expected.revision = 58;
    assert_eq!(v.try_adopt_inactive(p,peer(),false,&mut c,Dependencies::default()),
        Ok(InactiveProjection { disposition: InactiveDisposition::Adopted, route_action: RouteAction::CopyIncoming }));
    whole(v,expected); assert!(c.calls.is_empty()); assert_eq!(prepared_wire(p),before);
    for slot in SLOTS.into_iter().take(9) { assert!(matches!(v.policy.time_edit(slot),TimeEdit::Set(Origin {
        source: TimeSource::CorrespondingPreparedInput(s),delta:0 }) if s==slot)); }
    assert_eq!(v.time_edit(TimeSlot::EvidenceTime),TimeEdit::Retain);
}

#[test]
fn continuation_clock_inactive_suspension_lazy_L_and_resume_thresholds() {
    let mut seed = healthy(owner()); seed.policy.stable_resume = 4;
    seed.policy.maximum_resume = 2; seed.policy.suspension_pressure = 9;
    for branch in 0..6 {
        let mut v = seed;
        match branch { 1 => v.policy.stable_resume = 15, 2 => v.policy.tier = Tier::Survival,
            3 => v.policy.maximum_resume = 63, 4 => v.policy.rtt.raw.health = 0,
            5 => v.policy.rtt.raw.age_present = 0, _ => {} }
        let before = v; let p = prepared(v); let mut expected = before; corresponding(&mut expected.policy);
        expected.policy.suspension_pressure = 0; expected.policy.maximum_resume += 1; expected.revision = 58;
        let resume = branch==1 || branch==2 || branch==3;
        expected.policy.stable_resume = if branch==0 {5} else {0};
        if branch==2 || branch==3 { expected.policy.maximum_resume = 0; }
        let mut c = NativeCuts::default();
        assert_eq!(v.try_adopt_inactive(p,peer(),true,&mut c,Dependencies::default()),
            Ok(InactiveProjection { disposition: if resume { InactiveDisposition::BeginNativeResume }
                else { InactiveDisposition::Adopted }, route_action: RouteAction::CopyIncoming }));
        assert_eq!(c.calls,if branch<2 {vec![L]} else {vec![]}); whole(v,expected);
    }
}

