#[test]
fn continuation_clock_inactive_every_LQ_denial_discards_local_mutations_before_owner_revision() {
    let mut seed = healthy(probe(owner())); seed.policy.tier = Tier::AudioPriority;
    // Native admission sees a consumed invalid reserved word only after L.
    // No injected producer is used to manufacture the expected fault.
    seed.policy.rtt.raw.reserved = 1;
    seed.policy.suspension_pressure = 9; seed.policy.maximum_resume = 2; seed.policy.stable_resume = 4;
    let p = prepared(seed); let deps = Dependencies::default();
    for ordinal in 0..2 {
        let mut v = seed; let mut c = NativeCuts {fail:Some(ordinal),..Default::default()};
        assert_eq!(v.try_adopt_inactive(p,peer(),true,&mut c,deps),Err(deny(ordinal,[L,Q][ordinal])));
        assert_eq!(c.calls,[L,Q][..=ordinal]); whole(v,seed); whole_prepared(p,prepared(seed));
    }
    let mut v = seed; let mut expected = seed; corresponding(&mut expected.policy);
    expected.policy.suspension_pressure = 0; expected.policy.maximum_resume = 3;
    expected.policy.rtt.faulted = true; before_revert_cut(&mut expected.policy); after_revert_cut(&mut expected.policy);
    expected.revision = 58; let mut c = NativeCuts::default();
    assert_eq!(v.try_adopt_inactive(p,peer(),true,&mut c,deps),
        Ok(InactiveProjection {disposition:InactiveDisposition::Adopted,route_action:RouteAction::CopyIncoming}));
    assert_eq!(c.calls,[L,Q]); whole(v,expected);
}

