#[test]
fn continuation_clock_failure_FQ_denial_retains_fault_and_pre_Q_not_trailing_cleanup_or_revision() {
    let mut seed=healthy(probe(owner()));seed.policy.rtt.raw.advancement_present=0;
    // Opaque current raw/time mismatch is denied at the actual F consumption,
    // not globally normalized/rejected and not produced by the reducer oracle.
    let mut p=observed_negative(prepared(seed));
    p.capacity_only=true;p.policy.capacity_sequence=Some(42);p.policy.capacity_timestamp=Some(Scalar::new(42_000_000.0));
    let deps=Dependencies::default();
    for ordinal in 0..2 {
        let mut expected=seed;negative_prefix(&mut expected,p);expected.policy.capacity_sequence=Some(42);
        expected.policy.capacity_timestamp=p.policy.capacity_timestamp;
        if ordinal==1 {expected.policy.rtt.faulted=true;before_revert_cut(&mut expected.policy);}
        let mut v=seed;let mut c=NativeCuts{fail:Some(ordinal),..Default::default()};
        assert_eq!(v.try_finish_failure(p,facts(),&mut c,deps),Err(deny(ordinal,[F,Q][ordinal])));
        assert_eq!(c.calls,[F,Q][..=ordinal]);whole(v,expected);
    }
    let mut expected=seed;negative_prefix(&mut expected,p);expected.policy.capacity_sequence=Some(42);
    expected.policy.capacity_timestamp=p.policy.capacity_timestamp;expected.policy.rtt.faulted=true;
    before_revert_cut(&mut expected.policy);after_revert_cut(&mut expected.policy);expected.revision=58;
    let mut v=seed;let mut c=NativeCuts::default();
    assert_eq!(v.try_finish_failure(p,facts(),&mut c,deps),
        Ok(FailureProjection{disposition:FailureDisposition::RetainedFastIdentity,route_action:RouteAction::Retain}));
    assert_eq!(c.calls,[F,Q]);whole(v,expected);
}

