#[test]
fn continuation_clock_infallible_entrypoints_forward_same_shared_success_body() {
    // Supplemental only: literal-successor cases above remain the primary oracle.
    let mut seed=healthy(probe(owner()));seed.policy.tier=Tier::AudioPriority;
    let p=prepared(seed);let mut actual=seed;let mut forwarded=seed;
    let mut a=NativeCuts::default();let mut b=ForwardCuts::default();
    let result=actual.try_adopt_inactive(p,peer(),true,&mut a,Dependencies::default()).unwrap();
    assert_eq!(result,forwarded.adopt_inactive(p,peer(),true,&mut b,Dependencies::default()));
    assert_eq!(a.calls,b.calls);whole(actual,forwarded);
    let p=observed_negative(prepared(seed));let mut actual=seed;let mut forwarded=seed;
    let mut a=NativeCuts::default();let mut b=ForwardCuts::default();
    let result=actual.try_begin_active_apply(p,resources(),&mut a,Dependencies::default()).unwrap();
    assert_eq!(result,forwarded.begin_active_apply(p,resources(),&mut b,Dependencies::default()));
    assert_eq!(a.calls,b.calls);whole(actual,forwarded);
    let mut p=p;p.capacity_only=true;p.policy.capacity_sequence=Some(42);
    let mut actual=seed;let mut forwarded=seed;let mut a=NativeCuts::default();let mut b=ForwardCuts::default();
    let result=actual.try_finish_failure(p,facts(),&mut a,Dependencies::default()).unwrap();
    assert_eq!(result,forwarded.finish_failure(p,facts(),&mut b,Dependencies::default()));
    assert_eq!(a.calls,b.calls);whole(actual,forwarded);
}

